<script setup lang="ts">
import ModalDialog from '../components/ModalDialog.vue';
import CharacterListAdd from '../components/CharacterListAdd.vue';
import {confirmAction,promptAction} from '../lib/dialog';
import {orderCharacters} from '../lib/character-order';
import { ref,computed,onMounted,watch } from 'vue';import EventPicker from '../components/EventPicker.vue';import { api,ApiError,catalog } from '../lib/api';import type { Character,CharacterList } from '../../shared/models';
const addingMembers=ref<CharacterList|null>(null),memberBusy=ref(false),loading=ref(false);
const staleLists=ref<string[]>([]),loadFailed=ref(false);
let loadSequence=0,loadedEventId='';
const chars=ref<Character[]>([]),lists=ref<CharacterList[]>([]),query=ref(''),listId=ref(''),showHidden=ref(false),error=ref(''),notice=ref(''),busy=ref(false),newNames=ref(''),newList=ref(''),color=ref('#80636f'),editing=ref<Character|null>(null),editName=ref(''),editColor=ref(''),editFavorite=ref(false),editHidden=ref(false),editArchive=ref(false);
async function load(){
 const eventId=catalog.eventId,sequence=++loadSequence;
 if(!eventId){chars.value=[];lists.value=[];loading.value=false;return false;}
 if(eventId!==loadedEventId){chars.value=[];lists.value=[];}
 loading.value=true;
 try{const snapshot=await api<{characters:Character[];lists:CharacterList[]}>('/api/admin/events/'+eventId+'/characters');if(sequence!==loadSequence||eventId!==catalog.eventId)return false;chars.value=orderCharacters(snapshot.characters.filter(c=>c.id!=='aux-narrator'));lists.value=snapshot.lists;loadedEventId=eventId;staleLists.value=[];loadFailed.value=false;return true;}
 catch(e){if(sequence===loadSequence&&eventId===catalog.eventId){loadFailed.value=true;error.value=(e as Error).message;}return false;}
 finally{if(sequence===loadSequence)loading.value=false;}
}
watch(()=>catalog.eventId,()=>{listId.value='';query.value='';notice.value='';error.value='';addingMembers.value=null;memberBusy.value=false;void load();});onMounted(load);
const currentList=computed(()=>lists.value.find(l=>l.id===listId.value&&!l.archived));
const listBlocked=computed(()=>busy.value||loading.value||memberBusy.value||!!addingMembers.value||loadFailed.value||staleLists.value.includes(listId.value));
async function refreshLists(){if(busy.value||loading.value||memberBusy.value||addingMembers.value)return;error.value='';notice.value='';if(await load()){if(listId.value&&!currentList.value)listId.value='';notice.value='列表已刷新，请核对后继续操作。';}}
function openMembers(list:CharacterList){if(listBlocked.value)return;addingMembers.value={...list,members:[...list.members]};error.value='';notice.value='';}
function closeMembers(){if(!memberBusy.value)addingMembers.value=null;}
async function addedMembers(count:number,eventId:string,name:string){if(eventId!==catalog.eventId)return;addingMembers.value=null;memberBusy.value=false;query.value='';notice.value=`已将 ${count} 位角色加入「${name}」。`;await load();}

const names=computed(()=>Array.from(new Set(newNames.value.split(/\n|，|,/).map(x=>x.trim()).filter(Boolean))));const filtered=computed(()=>chars.value.filter(c=>(showHidden.value||(!c.hidden&&!c.archived))&&(!listId.value||lists.value.find(l=>l.id===listId.value)?.members.includes(c.id))&&[c.name,c.japanese_name,...c.aliases??[],c.display_name??''].some(x=>x.toLowerCase().includes(query.value.toLowerCase()))).sort((a,b)=>listId.value?(lists.value.find(l=>l.id===listId.value)!.members.indexOf(a.id)-lists.value.find(l=>l.id===listId.value)!.members.indexOf(b.id)):Number(b.favorite??0)-Number(a.favorite??0)));
async function op(data:object){await api('/api/admin/events/'+catalog.eventId+'/characters/operations',{...data,operation_id:crypto.randomUUID()});}
async function add(){if(listBlocked.value||!names.value.length)return;busy.value=true;error.value='';notice.value='';let added=0,skipped=0;try{for(const name of names.value){if(chars.value.some(c=>c.event_id===catalog.eventId&&c.name===name&&!c.archived)){skipped++;continue;}await op({type:'character.add',id:crypto.randomUUID(),name,color:color.value,list_id:listId.value||null});added++;await load();}newNames.value='';query.value='';notice.value=`已添加 ${added} 位角色${skipped?'，跳过 '+skipped+' 位已有角色':''}。已清除搜索筛选。`;}catch(e){error.value=`已添加 ${added} 位角色；`+(e as Error).message;}finally{busy.value=false;}}
async function addList(){if(busy.value||loading.value||memberBusy.value||!newList.value.trim())return;busy.value=true;error.value='';notice.value='';const id=crypto.randomUUID(),name=newList.value.trim();try{await op({type:'list.add',id,name});newList.value='';await load();listId.value=id;query.value='';notice.value=`已创建并选中「${name}」，可以添加已有角色或新角色。`;const list=lists.value.find(l=>l.id===id);if(list)addingMembers.value={...list,members:[...list.members]};}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function edit(c:Character){if(busy.value||loading.value||memberBusy.value||addingMembers.value)return;editing.value=c;editName.value=c.display_name??c.name;editColor.value=c.color;editFavorite.value=!!c.favorite;editHidden.value=!!c.hidden;editArchive.value=!!c.archived;}
async function save(){if(!editing.value||busy.value||loading.value||memberBusy.value)return;busy.value=true;try{const c=editing.value;if(c.kind==='custom')await op({type:'character.update',id:c.id,expectedVersion:c.version,name:editName.value,color:editColor.value,archived:editArchive.value});await op({type:'character.override',id:c.id,expectedVersion:c.override_version??0,color:editColor.value,display_name:c.kind==='custom'?null:editName.value===c.name?null:editName.value,hidden:editHidden.value,favorite:editFavorite.value});await load();editing.value=null;}catch(e){error.value=(e as Error).message;await load();}finally{busy.value=false;}}
async function updateList(list:CharacterList,members:string[],archive=false){
 if(listBlocked.value)return;
 // Lock synchronously, including confirmation and the fresh read after saving.
 busy.value=true;
 try{
  if(archive&&!await confirmAction('归档此角色列表？角色及历史台词仍会保留。'))return;
  error.value='';notice.value='';
  await op({type:'list.update',id:list.id,expectedVersion:list.version,name:list.name,archived:archive,position:list.position,members});
  if(archive)listId.value='';
  await load();
 }catch(e){
  if(e instanceof ApiError&&e.status===409){if(!staleLists.value.includes(list.id))staleLists.value.push(list.id);error.value='角色列表已被修改，请点击「刷新列表」核对后重试。';}
  else error.value=(e as Error).message;
 }finally{busy.value=false;}
}
function cannotMove(c:Character,offset:number){const members=currentList.value?.members??[],index=members.indexOf(c.id);return listBlocked.value||index<0||index+offset<0||index+offset>=members.length;}
async function membership(c:Character){if(listBlocked.value)return;const list=currentList.value;if(!list)return;await updateList(list,list.members.filter(id=>id!==c.id));}
async function moveMember(c:Character,offset:number){if(cannotMove(c,offset))return;const list=currentList.value!;const members=[...list.members],index=members.indexOf(c.id),next=index+offset;[members[index],members[next]]=[members[next]!,members[index]!];await updateList(list,members);}
async function archiveList(){const list=currentList.value;if(!list||listBlocked.value)return;await updateList(list,[...list.members],true);}
</script>
<template><div class="page"><header class="page-head"><div><h1>角色库</h1></div><EventPicker :disabled="busy||loading||!!addingMembers"/></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><div class="filters paper"><FieldLabel>查找角色<input v-model="query" type="search" placeholder="中文名 / 日文名 / 别名"></FieldLabel><FieldLabel>角色列表<select v-model="listId" aria-label="角色列表" :disabled="busy||loading||!!addingMembers"><option value="">全部角色</option><option v-for="l in lists.filter(l=>!l.archived)" :value="l.id">{{ l.name }}</option></select></FieldLabel><FieldLabel class="check"><input type="checkbox" v-model="showHidden">显示隐藏或已归档</FieldLabel></div><section v-if="currentList" class="paper list-members"><div><h2>{{ currentList.name }}</h2><p class="hint">列表内 {{ currentList.members.length }} 位角色</p></div><div class="list-member-actions"><button type="button" :disabled="busy||loading||memberBusy||!!addingMembers" @click="refreshLists">刷新列表</button><button type="button" class="primary" :disabled="listBlocked" @click="openMembers(currentList)">添加角色</button></div></section><div class="character-grid"><article v-for="c in filtered" :key="c.id" class="character-card" :style="{'--character-color':c.color}"><span class="character-symbol">{{ c.display_name?.slice(0,1)??c.name.slice(0,1) }}</span><div><h3>{{ c.display_name??c.name }} <span v-if="c.favorite">★</span></h3><small>{{ c.japanese_name||'活动自定义角色' }}</small><p class="hint">{{ c.aliases?.join(' · ') }}</p><small v-if="c.sources?.some(s=>s.verification==='supplementary-needs-primary-check')">补充条目 · 待官方资料核对</small><small v-if="c.hidden||c.archived">{{ c.archived?'已归档':'已隐藏' }}</small></div><div class="inline"><button :disabled="busy||loading||memberBusy" @click="edit(c)">设置</button><button v-if="listId" aria-label="角色在列表内上移" :disabled="cannotMove(c,-1)" @click="moveMember(c,-1)">↑</button><button v-if="listId" aria-label="角色在列表内下移" :disabled="cannotMove(c,1)" @click="moveMember(c,1)">↓</button><button v-if="listId" :disabled="listBlocked" @click="membership(c)">从列表移除</button></div></article></div><p v-if="!filtered.length" class="empty">没有符合条件的角色。</p><div class="grid two"><section class="paper"><h2>批量添加活动角色</h2><FieldLabel>名称（每行一个，自动去重）<textarea v-model="newNames" rows="4"></textarea></FieldLabel><p class="hint">预览：{{ names.join('、')||'等待输入' }}</p><FieldLabel>应援色<input v-model="color" type="color"></FieldLabel></section><section class="paper"><h2>建立角色列表</h2><form id="character-list-form" class="inline" @submit.prevent="addList"><FieldLabel>新角色列表名称<input v-model="newList" required placeholder="例如：开场主持组" aria-label="新角色列表名称"></FieldLabel></form><p class="hint">创建后可直接选择角色；已有列表可在列表上方点击「添加角色」。</p><a class="hint" href="https://gochiusa.com/chara/" target="_blank" rel="noopener noreferrer">官方角色资料 ↗</a></section></div><PageActions><button v-if="listId" type="button" :disabled="listBlocked" @click="archiveList">归档列表</button><button type="submit" form="character-list-form" :disabled="busy||loading||memberBusy">创建角色列表</button><button type="button" class="primary" :disabled="listBlocked||!names.length" @click="add">添加 {{ names.length }} 位角色{{ listId?'至当前列表':'' }}</button></PageActions><CharacterListAdd v-if="addingMembers" :event-id="catalog.eventId" :list="addingMembers" :characters="chars" @close="closeMembers" @added="addedMembers" @busy="memberBusy=$event"/><ModalDialog v-if="editing" :title="editing.name+' · 角色设置'" @close="editing=null"><form @submit.prevent="save"><FieldLabel>{{ editing.kind==='custom'?'名称':'本活动显示名' }}<input v-model="editName" required></FieldLabel><FieldLabel>应援色<input v-model="editColor" type="color"></FieldLabel><FieldLabel class="check"><input v-model="editFavorite" type="checkbox">收藏</FieldLabel><FieldLabel class="check"><input v-model="editHidden" type="checkbox">从角色选择器隐藏</FieldLabel><FieldLabel v-if="editing.kind==='custom'" class="check"><input v-model="editArchive" type="checkbox">归档（保留历史台词）</FieldLabel><div class="inline"><button type="button" @click="editing=null">取消</button><button class="primary" :disabled="busy">保存</button></div></form></ModalDialog></div></template>

<style scoped>
.list-members{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.list-members h2{font-size:20px;margin:0}.list-members p{margin:6px 0 0}.list-members button{flex-shrink:0}.list-member-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}@media(max-width:760px){.list-members{padding:16px;gap:10px;flex-wrap:wrap}.list-members h2{font-size:17px;overflow-wrap:anywhere}.list-members>div{min-width:0}.list-member-actions{width:100%}}
</style>
